// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Place-assertion spec functions of property `too_cold_heats` -- one per
//! point its decoration binds (unbound points carry `true`, design D5).

#![allow(non_snake_case)]
#![allow(unused_imports)]

use data::*;
use vstd::prelude::*;

use crate::assertions::*;
use crate::system_state::SystemState;

verus! {

/** property too_cold_heats, bound 'at START' (place START)
  *   established initially by the initialize guarantees (all Off; set
  *   points 98..101)
  */
pub open spec fn sys_assert_too_cold_heats_START(st: SystemState) -> bool
{
  (st.heaterState == st.lastCmd) &&
    (st.setPoints.lower.degrees <= st.setPoints.upper.degrees)
}

/** property too_cold_heats, bound 'after oi' (place after_oi)
  *   carried across the Operator Interface (it touches neither)
  */
pub open spec fn sys_assert_too_cold_heats_after_oi(st: SystemState) -> bool
{
  (st.heaterState == st.lastCmd) &&
    (st.setPoints.lower.degrees <= st.setPoints.upper.degrees)
}

/** property too_cold_heats, bound 'after sensor' (place after_sensor)
  *   carried across the Temp Sensor; discharges the Thermostat's
  *   INV_CSP assume
  */
pub open spec fn sys_assert_too_cold_heats_after_sensor(st: SystemState) -> bool
{
  (st.heaterState == st.lastCmd) &&
    (st.setPoints.lower.degrees <= st.setPoints.upper.degrees)
}

/** property too_cold_heats, bound 'after therm' (place after_therm)
  *   send-on-change: either the new command is on its way, or the
  *   command did not change and the heater already agrees with it
  */
pub open spec fn sys_assert_too_cold_heats_after_therm(st: SystemState) -> bool
{
  ((st.heatCmd.is_some() &&
    (st.heatCmd.unwrap() == st.lastCmd) ||
    !(st.heatCmd.is_some()) &&
      (st.heaterState == st.lastCmd)) &&
    (st.setPoints.lower.degrees <= st.setPoints.upper.degrees)) &&
    (st.tempChanged.is_some() &&
      (st.sensedTemp.degrees < st.setPoints.lower.degrees) ==>
      (st.lastCmd == Isolette_Data_Model::On_Off::Onn))
}

/** property too_cold_heats, bound 'after hs' (place after_hs)
  *   the Heat Source latched the command, if one arrived
  */
pub open spec fn sys_assert_too_cold_heats_after_hs(st: SystemState) -> bool
{
  ((st.heaterState == st.lastCmd) &&
    (st.setPoints.lower.degrees <= st.setPoints.upper.degrees)) &&
    (st.tempChanged.is_some() &&
      (st.sensedTemp.degrees < st.setPoints.lower.degrees) ==>
      (st.heaterState == Isolette_Data_Model::On_Off::Onn))
}

/** property too_cold_heats, bound 'at END' (place END)
  *   loop closure: END |- START
  */
pub open spec fn sys_assert_too_cold_heats_END(st: SystemState) -> bool
{
  (st.heaterState == st.lastCmd) &&
    (st.setPoints.lower.degrees <= st.setPoints.upper.degrees)
}

} // verus!
